const all = $("unir informes")
  .all()
  .map((e) => e.json);
const common = $input.first().json;
const fields_empresa = $("Edit Fields").first().json.empresa;
const fecha = fields_empresa.fecha;
const KEYS_BANNED_FOR_PRODUCT = [
  "id",
  "emp_name",
  "emp_code",
  "split_informe",
  "scope",
  "fecha",
];
const product_names = Object.keys(fields_empresa).filter(
  (key) => !KEYS_BANNED_FOR_PRODUCT.includes(key),
);
let checkin_product = [];

const category_id_product = {
  uas: [3],
  beyondtrust: [4, 5, 6, 7],
  invgate: [10, 11],
  "invgate.asj": [10, 11],
  wazuh: [61],
  akurtech: [66],
  whalemate: [137],
};

// ------------------------------------
// ARMADO DE FILAS + CATEGORY_IDS_MATTERS
// ------------------------------------
let requests = [];
let category_ids_matters = [];

const rows = all.flatMap((e) => {
  if (e?.requests) {
    requests = e.requests;
    return requests;
  }
  if (!Array.isArray(e.xlsxData)) return [];

  return e.xlsxData.map((r) => {
    // Si la fila tiene producto explícito
    if (r?.product) {
      const product_name = r.product;
      const check = product_names.includes(product_name);
      checkin_product.push({ product: product_name, checked: check });
      category_ids_matters.push(...category_id_product[product_name]);
    }

    // Si NO tiene product, lo heredamos del item padre
    if (!r.product && e.product) {
      return { ...r, product: e.product };
    }

    return r;
  });
});
checkin_product = product_names
  .map((name) => {
    if (fields_empresa[name] == 1) {
      const index = checkin_product.findIndex((e) => e.product == name);
      if (index != -1) {
        return checkin_product[index];
      } else {
        return { product: name, checked: false };
      }
    }
  })
  .filter((e) => Boolean(e));

// -----------------------------------------
// COMMON Y PRODUCTS
// -----------------------------------------
const company_name = $("Search Carpeta Cliente")
  .first()
  .json.name.toLowerCase();

const products = rows.filter((r) => r.Semana);

function throwIfEmptyInSemanaObject(obj) {
  const product_name = products[0]?.product
  if (
    !obj ||
    typeof obj !== "object" ||
    typeof obj.Semana !== "string" ||
    !obj.Semana.includes("Semana")
  ) {
    return;
  }

  Object.entries(obj).forEach(([key, value]) => {
    if (value === "") {
      throw new Error(
        `El Archivo ${product_name}.xlsx, tiene valor vacío detectado en "${key}" para ${obj.Semana}`
      );
    }
  });
}
products.forEach(throwIfEmptyInSemanaObject);

// -----------------------------------------
// FUNCIONES
// -----------------------------------------
const getV = (value) =>
  typeof value === "number" ? value : value === "null" ? "" : value;

if (requests.length > 0) {
  const baseDate = new Date(`${fecha}-01T00:00:00Z`);
  const baseMonth = baseDate.getUTCMonth();
  const baseYear = baseDate.getUTCFullYear();

  // Semana del mes con ajuste Semana5 → Semana4
  function getWeekOfMonth(dateUnix) {
    const d = new Date(dateUnix * 1000);
    const day = d.getDate();
    let week = Math.ceil(day / 7);
    if (week > 4) week = 4; // semana 5 se considera semana 4
    return week;
  }

  // -----------------------------------------
  // FILTRADO REQUESTS POR MES Y POR CATEGORY_ID
  // -----------------------------------------
  const filteredRequests = requests.filter((r) => {
    const d = new Date(Number(r.created_at) * 1000);
    return (
      d.getUTCFullYear() === baseYear &&
      d.getUTCMonth() === baseMonth &&
      category_ids_matters.includes(parseInt(r.category_id))
    );
  });

  // -----------------------------------------
  // GROUPED REQUESTS POR SEMANA
  // -----------------------------------------
  const grouped = filteredRequests.reduce((acc, r) => {
    const week = getWeekOfMonth(Number(r.created_at));
    if (!acc[week]) acc[week] = [];
    acc[week].push(r);
    return acc;
  }, {});

  // -----------------------------------------
  // ASIGNAR REQUESTS A CADA PRODUCTO POR SEMANA
  // -----------------------------------------
  let product_name = "";
  const semanas = ["Semana 1", "Semana 2", "Semana 3", "Semana 4"];

  Object.keys(grouped).forEach((week) => {
    products.forEach((data) => {
      // Cada vez que aparece un product, cambiamos el producto activo
      if (data?.product) {
        product_name = data.product.split(".")[0];
      }

      // Validamos semana matcheando número
      if (
        semanas.includes(data.Semana) &&
        (data.Semana.includes(week) ||
          (data.Semana === "Semana 4" && week === "5"))
      ) {
        const relevantRequests = grouped[week].filter((req) =>
          category_id_product[product_name].includes(parseInt(req.category_id)),
        );

        // Encontrar key tipo: Consulta, Consultas, Q1, etc.
        const keys = Object.keys(data);
        const index_k = keys.findIndex((k) =>
          ["Consultas Respondidas", "Tickets cerrados"].includes(k),
        );
        const key = keys[index_k];

        data[key] = relevantRequests.length;
      }
    });
  });
}

