const today = new Date();
const dayOfMonth = today.getDate();
const month = today.getMonth(); // Enero es 0, Diciembre es 11
const year = today.getFullYear();

let businessDayCount = 0;

// 1. Calcular cuántos días hábiles han pasado en el mes actual
for (let i = 1; i <= dayOfMonth; i++) {
  const dateToCheck = new Date(year, month, i);
  const dayOfWeek = dateToCheck.getDay();
  // Lunes (1) a Viernes (5)
  if (dayOfWeek >= 1 && dayOfWeek <= 5) {
    businessDayCount++;
  }
}

// 2. Condición: ¿Estamos dentro de los primeros 10 días hábiles?
// También verifica que hoy no sea sábado (6) o domingo (0)
const isWithinFirstTen = businessDayCount <= 10 && (today.getDay() >= 1 && today.getDay() <= 5);

// 3. Calcular el "Mes a Analizar" (Mes Anterior)
let prevMonth = month; // Si hoy es Diciembre (11), prevMonth será 11 (que representa Noviembre en formato humano)
let prevYear = year;

if (month === 0) { // Si es Enero, el mes anterior es Diciembre del año pasado
  prevMonth = 12;
  prevYear = year - 1;
}

// Formatear el mes con dos dígitos (ej: "01", "11")
const monthFormatted = prevMonth.toString().padStart(2, '0');
const date_analizar = `${prevYear}-${monthFormatted}`;

return [
  {
    json: {
      dia_habil_actual: businessDayCount,
      date_analizar,
      isWithinFirstTen
    },
  },
];

