let filtered_companies = $("Lista de Empresas con folderID").all();

const response_logs = Array.isArray($input.all()) ? $input.all() : [];
//const response_logs = Array.isArray(data) ? data : [];
const companies = [];
filtered_companies.forEach((emp) => {
  if (emp.json.empresas) {
    companies.push(...emp.json.empresas);
  } else {
    companies.push(emp.json.empresa);
  }
});

function isSplitConfig(item) {
  return (
    !Array.isArray(item.logs) &&
    Array.isArray(item.links) &&
    item.links.length > 1
  );
}

function normalizeItem(item, companies) {
  const result = [];

  const hasSplitConfig = isSplitConfig(item);
  const company = companies.find((c) => c.emp_code === item.emp_code);

  // MULTI EMPRESA (no split)
  if (Array.isArray(item.logs)) {
    const link = item.links?.[0];

    item.logs.forEach((logBlock) => {
      const comp = companies.find(
        (c) => c.emp_code === logBlock.emp_code
      );

      result.push({
        emp_code: logBlock.emp_code,
        emp_name: comp?.emp_name || logBlock.emp_code,
        link,
        products: logBlock.logs?.checked_products || [],
      });
    });

    return result;
  }

  // EMPRESA ÚNICA
  const products = (item.logs?.checked_products || []).map((p, i) => ({
    ...p,
    link: hasSplitConfig ? item.links?.[i] : item.links?.[0],
  }));

  result.push({
    emp_code: item.emp_code,
    emp_name: company?.emp_name || item.emp_code,
    link: hasSplitConfig ? null : item.links?.[0],
    products,
  });

  return result;
}

const response = response_logs.reduce(
  (prev, curr) => {
    if (curr.json.code !== 200) {
      prev.errors.push(curr.json);
      return prev;
    }

    const normalized = normalizeItem(curr.json, companies);
    prev.ok.push(...normalized);

    return prev;
  },
  { ok: [], errors: [] },
);

